-- Conventions for every migration:
--  * ids are bigint; tables that grow at runtime take them from a per-table sequence
--    (INCREMENT BY 50 = Hibernate allocationSize, so inserts can be batched).
--  * Sequences START WITH 1000 so ids generated by Hibernate never collide with the
--    explicit ids used by reference and demo data.
--  * Enums are varchar + CHECK (adding a value is a plain constraint change).
--  * Timestamps are timestamptz (UTC instants).

CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS unaccent;

-- unaccent() is STABLE, so it cannot be used in an index expression. This wrapper pins the
-- dictionary, which makes it safe to declare IMMUTABLE.
CREATE FUNCTION immutable_unaccent(text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT
AS $$ SELECT public.unaccent('public.unaccent'::regdictionary, $1) $$;

CREATE TABLE region (
    region_id  bigint       PRIMARY KEY,
    name       varchar(100) NOT NULL,
    sort_order integer      NOT NULL,
    CONSTRAINT uk_region_name UNIQUE (name)
);

CREATE TABLE commune (
    commune_id bigint       PRIMARY KEY,
    region_id  bigint       NOT NULL REFERENCES region (region_id),
    name       varchar(100) NOT NULL,
    CONSTRAINT uk_commune_region_name UNIQUE (region_id, name)
);

CREATE SEQUENCE service_seq START WITH 1000 INCREMENT BY 50;

CREATE TABLE service (
    service_id bigint       PRIMARY KEY,
    name       varchar(150) NOT NULL,
    is_active  boolean      NOT NULL DEFAULT true,
    CONSTRAINT uk_service_name UNIQUE (name)
);

CREATE TABLE age_range (
    age_range_id bigint      PRIMARY KEY,
    description  varchar(50) NOT NULL,
    sort_order   integer     NOT NULL,
    CONSTRAINT uk_age_range_description UNIQUE (description)
);

CREATE TABLE gender (
    gender_id   bigint      PRIMARY KEY,
    description varchar(50) NOT NULL,
    CONSTRAINT uk_gender_description UNIQUE (description)
);
